package com.aptech.s06lab;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;

/**
 * REPAIR CLINIC SELF-CHECK — run this class to test your repairs. Aim for all PASS.
 *
 * DO NOT EDIT THIS FILE. It is the same shape as the A3 SelfCheck: each check names the fault,
 * and a FAIL tells you the method and what it expected. Run it again after every single repair.
 */
public class SelfCheck {

    private static int passed = 0;
    private static int failed = 0;

    interface Test { void run() throws Exception; }

    public static void main(String[] args) {
        System.out.println("=== Repair Clinic Self-Check ===\n");

        run("F1  Session 1 - each student listed once, in first-seen order", () -> {
            List<String> ids = List.of("S-1003", "S-1001", "S-1003", "S-1002", "S-1001");
            List<String> distinct = RepairClinic.distinctStudents(ids);
            check(distinct != null, "distinctStudents returned null");
            check(distinct.size() == 3,
                    "expected 3 students, got " + distinct.size() + " -> " + distinct);
            check(new LinkedHashSet<>(distinct).size() == distinct.size(),
                    "the result still contains duplicates: " + distinct);
            check(distinct.get(0).equals("S-1003") && distinct.get(1).equals("S-1001"),
                    "first-seen order was not kept (expected [S-1003, S-1001, S-1002]): " + distinct);
        });

        run("F2  Session 2 - adds up integer marks and decimal marks alike", () -> {
            long integers = RepairClinic.sumMarks(List.of(70, 85));
            check(integers == 155, "integers: expected 155, got " + integers);
            long decimals = RepairClinic.sumMarks(List.of(70.5, 85.5));
            check(decimals == 156, "decimals: expected 156, got " + decimals);
        });

        run("F3  Session 3 - the report really reaches the disk", () -> {
            Path dir = Path.of("selfcheck-tmp");
            Files.createDirectories(dir);
            Path file = dir.resolve("f3-report.txt");
            Files.deleteIfExists(file);

            RepairClinic.saveReport(file, List.of("S-1001,Ada", "S-1002,Ben", "S-1003,Chioma"));

            check(Files.exists(file), "the report file was never created");
            List<String> back = Files.readAllLines(file);
            check(back.size() == 3,
                    "expected 3 lines on disk, found " + back.size()
                            + " - is the writer being closed?");
        });

        run("F4  Session 4 - countAlive follows the workers' life", () -> {
            List<Thread> workers = new ArrayList<>(List.of(
                    new Thread(() -> sleep(300), "worker-1"),
                    new Thread(() -> sleep(300), "worker-2")));

            check(RepairClinic.countAlive(workers) == 0,
                    "threads that have never been started are not alive");
            workers.forEach(Thread::start);
            check(RepairClinic.countAlive(workers) == 2,
                    "both workers are alive immediately after start()");
            for (Thread worker : workers) {
                worker.join(2000);
            }
            check(RepairClinic.countAlive(workers) == 0,
                    "no worker is alive once join() has returned");
        });

        run("F5  Session 5 - the files are processed at the same time", () -> {
            List<String> files = List.of("a.log", "b.log", "c.log");
            long start = System.currentTimeMillis();
            Map<String, Integer> tally = RepairClinic.processAll(files, 20, 20);
            long took = System.currentTimeMillis() - start;

            check(tally != null, "processAll returned null");
            int total = tally.values().stream().mapToInt(Integer::intValue).sum();
            check(total == 60, "expected 60 lines in the tally, found " + total + " -> " + tally);
            check(took < 900,
                    "3 files of 20 lines x 20 ms took " + took
                            + " ms - one after another is about 1200 ms. Are they overlapping?");
        });

        System.out.println("\n" + passed + " passed, " + failed + " failed.");
        System.out.println(failed == 0
                ? "Every fault repaired - the clinic is closed."
                : "Repair the FAILs above one at a time, then run SelfCheck again.");
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void sleep(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static void run(String name, Test test) {
        try {
            test.run();
            passed++;
            System.out.println("PASS  " + name);
        } catch (AssertionError e) {
            failed++;
            System.out.println("FAIL  " + name + "\n      -> " + e.getMessage());
        } catch (Exception e) {
            failed++;
            System.out.println("FAIL  " + name + "\n      -> crashed with " + e);
        }
    }
}
